'use strict';

const PROCEDURES = [
  { name: 'Лапароскопическая холецистэктомия', profile: 'Общая хирургия', diagnosis: 'Желчнокаменная болезнь' },
  { name: 'Пластика паховой грыжи', profile: 'Общая хирургия', diagnosis: 'Паховая грыжа' },
  { name: 'Операция по поводу катаракты', profile: 'Офтальмология', diagnosis: 'Возрастная катаракта' },
  { name: 'Артроскопия коленного сустава', profile: 'Травматология', diagnosis: 'Повреждение мениска' },
  { name: 'Эндовенозная лазерная облитерация', profile: 'Сосудистая хирургия', diagnosis: 'Варикозная болезнь' },
  { name: 'Септопластика', profile: 'Оториноларингология', diagnosis: 'Искривление перегородки носа' },
];
const CLINICS = [
  { id: 'c1', name: 'Демо-клиника «Уральская»', city: 'Челябинск', procedure: 0, payment: 'both', slots: 4, date: '2026-10-08', price: 68000 },
  { id: 'c2', name: 'Демо-центр «Южный»', city: 'Копейск', procedure: 1, payment: 'oms', slots: 3, date: '2026-10-12', price: 0 },
  { id: 'c3', name: 'Демо-клиника «Ясный взгляд»', city: 'Челябинск', procedure: 2, payment: 'both', slots: 6, date: '2026-10-09', price: 52000 },
  { id: 'c4', name: 'Демо-центр «Движение»', city: 'Миасс', procedure: 3, payment: 'oms', slots: 2, date: '2026-10-14', price: 0 },
  { id: 'c5', name: 'Демо-клиника «Ритм»', city: 'Магнитогорск', procedure: 4, payment: 'paid', slots: 5, date: '2026-10-07', price: 46000 },
  { id: 'c6', name: 'Демо-центр «Дыхание»', city: 'Челябинск', procedure: 5, payment: 'both', slots: 3, date: '2026-10-15', price: 57000 },
];
const STATUS = { draft:'Черновик', waiting:'В поиске стационара', clarification:'Нужно уточнение', review:'Получено предложение', confirmed:'Предложение подтверждено', admitted:'Госпитализирован', no_show:'Неявка на госпитализацию', documents:'Не предоставлен полный пакет документов', completed:'Случай завершён', cancelled:'Заявка отменена', archived:'Архив' };
const PAYMENT = { oms: 'ОМС', paid: 'Платно', both: 'ОМС / платно' };
const seed = [
  [1042,58,'Златоуст',0,'oms',true,'waiting',true],
  [1041,67,'Челябинск',2,'oms',true,'waiting',false],
  [1040,42,'Копейск',1,'oms',false,'waiting',true],
  [1039,35,'Магнитогорск',4,'paid',true,'waiting',false],
  [1038,49,'Миасс',3,'oms',true,'review',false],
  [1037,29,'Челябинск',5,'oms',true,'waiting',true],
  [1036,63,'Сатка',0,'oms',true,'review',true],
  [1035,72,'Копейск',2,'oms',true,'confirmed',true],
  [1034,46,'Челябинск',1,'oms',true,'waiting',false],
  [1033,51,'Магнитогорск',4,'oms',false,'waiting',true],
  [1032,38,'Златоуст',3,'oms',true,'confirmed',true],
  [1031,32,'Миасс',5,'paid',true,'review',true],
];
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel = value => new Date(value + 'T12:00:00').toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
const money = value => new Intl.NumberFormat('ru-RU').format(value) + ' ₽';
const ageLabel = age => { const n=age%100; return age+' '+(n>=11&&n<=14?'лет':age%10===1?'год':[2,3,4].includes(age%10)?'года':'лет'); };
const ROLE = { inpatient:'Врач стационара', outpatient:'Врач амбулатории', patient:'Пациент', admin:'Администратор' };
let patients, view = 'patients', role = 'inpatient', filters, clinicFilter = null, selectedId = null, editingId = null, toastTimer, auditLog=[];

function initialPatients() {
  return seed.map(([id,age,city,procedure,payment,ready,status,travel], index) => {
    const c=CLINICS.find(c=>c.procedure===procedure);
    return { id,age,city,procedure,payment,ready,status,travel,inPersonRequired:index%4===0,createdBy:index%3===0?'amb-1':index%3===1?'amb-2':'amb-3',created:`2026-10-${String(3-Math.floor(index/5)).padStart(2,'0')}`,
      offer: status==='waiting'?null:{clinicId:c.id,payment:payment==='paid'?'paid':'oms',date:c.date},offers:status==='waiting'?[]:[{id:`offer-${id}`,clinicId:c.id,payment:payment==='paid'?'paid':'oms',date:c.date}],
      history:[{text:'Создана пробная заявка',time:'Пример · октябрь 2026'},...(status==='waiting'?[]:[{text:'Добавлено предложение стационара',time:'Исходный демонстрационный сценарий'}]),...(status==='confirmed'?[{text:'Госпитализация согласована в демо',time:'Исходный демонстрационный сценарий'}]:[])] };
  });
}
function resetFilters(){filters={search:'',profile:'',city:'',payment:'',status:''};clinicFilter=null;}
function compatiblePayment(a,b){return a===b||a==='both'||b==='both';}
function matches(p,c){return p.procedure===c.procedure&&compatiblePayment(p.payment,c.payment)&&(p.travel||p.city===c.city);}
function availableSlots(c){return Math.max(0,c.slots-patients.filter(p=>p.status==='confirmed'&&p.offer?.clinicId===c.id).length);}
function matchingClinics(p){const offered=(p.offers||[]).map(o=>o.clinicId);return CLINICS.filter(c=>matches(p,c)&&availableSlots(c)>0&&!offered.includes(c.id));}
function visiblePatients(){if(role==='outpatient')return patients.filter(p=>p.createdBy==='amb-1');if(role==='inpatient')return patients.filter(p=>!['draft','archived'].includes(p.status));return patients;}
function counts(){const rows=visiblePatients();return {all:rows.length,...Object.fromEntries(Object.keys(STATUS).map(s=>[s,rows.filter(p=>p.status===s).length]))};}
function badge(value,type='status'){return `<span class="badge ${esc(value)}">${esc((type==='payment'?PAYMENT:STATUS)[value])}</span>`;}
function examFlag(p){if(!['inpatient','admin'].includes(role))return '';return `${p.inPersonRequired?'<span class="exam-flag">Требуется очный осмотр</span>':''}${p.needsReview?'<span class="review-flag">Изменена · повторно проверить</span>':''}`;}
function announce(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500);}
function openDialog(id){const d=document.getElementById(id);if(!d.open)d.showModal();}
function closeDialog(id){document.getElementById(id).close();}
function statsHTML(){const n=counts();return `<div class="stats"><div class="stat"><span>Всего заявок</span><strong>${n.all}</strong><small>В демонстрационном реестре</small></div><div class="stat"><span>Ожидают предложения</span><strong>${n.waiting}</strong><small>Можно подобрать стационар</small></div><div class="stat"><span>На согласовании</span><strong>${n.review}</strong><small>Пациент выбирает вариант</small></div><div class="stat accent"><span>Госпитализация подтверждена</span><strong>${n.confirmed}</strong><small>Дата и условия согласованы</small></div></div>`;}
function options(values,selected){return values.map(v=>`<option value="${esc(v)}"${v===selected?' selected':''}>${esc(v)}</option>`).join('');}
function filteredPatients(){return visiblePatients().filter(p=>{
  const proc=PROCEDURES[p.procedure];
  return (!filters.search||`Д-${p.id} ${p.city} ${proc.name} ${proc.diagnosis} ${proc.profile}`.toLocaleLowerCase('ru').includes(filters.search.toLocaleLowerCase('ru').trim()))
    &&(!filters.profile||proc.profile===filters.profile)&&(!filters.city||p.city===filters.city)
    &&(!filters.payment||compatiblePayment(p.payment,filters.payment))&&(!filters.status||p.status===filters.status)
    &&(!clinicFilter||matches(p,CLINICS.find(c=>c.id===clinicFilter)));
}).sort((a,b)=>a.created.localeCompare(b.created)||a.id-b.id);}
function tableHTML(){const rows=filteredPatients();return `<div class="results-summary"><span role="status">Найдено заявок: ${rows.length}</span><span class="sort-label">Старые заявки сверху · сценарий на 3 октября 2026</span></div>${rows.length?`<table class="patient-table"><caption class="visually-hidden">Демонстрационные пациенты и планируемые вмешательства</caption><colgroup><col style="width:20%"><col style="width:26%"><col class="payment-col" style="width:12%"><col class="readiness-col" style="width:16%"><col style="width:17%"><col style="width:9%"></colgroup><thead><tr><th>Пациент</th><th>Вмешательство</th><th>Оплата</th><th class="readiness-col">Обследования</th><th>Статус</th><th><span class="visually-hidden">Действия</span></th></tr></thead><tbody>${rows.map(p=>`<tr><td><button class="patient-id" data-open="${p.id}">Пациент Д-${p.id}</button><span class="subline">${ageLabel(p.age)} · ${esc(p.city)}</span>${examFlag(p)}</td><td><span class="procedure-title">${PROCEDURES[p.procedure].name}</span><span class="profile-label">${PROCEDURES[p.procedure].profile}</span></td><td>${badge(p.payment,'payment')}</td><td class="readiness-col"><span class="${p.ready?'ready':'not-ready'}">${p.ready?'✓ Собраны':'Нужны уточнения'}</span></td><td>${badge(p.status)}</td><td><button class="row-open" data-open="${p.id}" aria-label="Открыть пациента Д-${p.id}">Открыть</button></td></tr>`).join('')}</tbody></table><div class="table-footer">Показаны все ${rows.length} · Контактные данные в демоверсии отсутствуют</div>`:`<div class="empty"><h3>Подходящих заявок пока нет</h3><p>Измените условия поиска или сбросьте фильтры.</p><button class="button secondary" data-reset-filters>Сбросить фильтры</button></div>`}`;}
function renderPatients(){const n=counts();const rows=visiblePatients();return `${statsHTML()}${role==='outpatient'?'<div class="clinic-filter-note"><span>Показаны только заявки, созданные этим врачом в демо.</span><span>Врач амбулатории № 1</span></div>':''}${clinicFilter?`<div class="clinic-filter-note"><span>Подбор для ${esc(CLINICS.find(c=>c.id===clinicFilter).name)}</span><button class="text-button" data-reset-filters>Убрать подбор</button></div>`:''}<section class="panel"><div class="panel-header"><h2>${role==='outpatient'?'Мои заявки':'Реестр заявок'}</h2><span class="count-label">${rows.length} пациентов</span></div><div class="tabs" role="group" aria-label="Фильтр по статусу">${[['','Все заявки',n.all],['waiting','Ожидают',n.waiting],['review','На согласовании',n.review],['confirmed','Подтверждены',n.confirmed]].map(([s,label,count])=>`<button class="tab ${filters.status===s?'active':''}" data-status="${s}" aria-pressed="${filters.status===s}">${label}<span>${count}</span></button>`).join('')}</div><div class="filters"><label class="search"><span class="visually-hidden">Поиск по номеру, городу или вмешательству</span><input type="search" id="search" placeholder="Поиск по номеру, городу, вмешательству" value="${esc(filters.search)}"></label><label class="visually-hidden" for="profile-filter">Профиль помощи</label><select class="filter-select" id="profile-filter" data-filter="profile"><option value="">Все профили</option>${options([...new Set(PROCEDURES.map(p=>p.profile))],filters.profile)}</select><label class="visually-hidden" for="city-filter">Город пациента</label><select class="filter-select" id="city-filter" data-filter="city"><option value="">Все города</option>${options([...new Set(rows.map(p=>p.city))].sort(),filters.city)}</select><label class="visually-hidden" for="payment-filter">Вариант оплаты</label><select class="filter-select" id="payment-filter" data-filter="payment"><option value="">Любая оплата</option><option value="oms"${filters.payment==='oms'?' selected':''}>Рассматривают ОМС</option><option value="paid"${filters.payment==='paid'?' selected':''}>Рассматривают платно</option></select><label class="visually-hidden" for="status-filter">Статус заявки</label><select class="filter-select" id="status-filter" data-filter="status"><option value="">Любой статус</option>${Object.entries(STATUS).map(([key,label])=>`<option value="${key}"${filters.status===key?' selected':''}>${label}</option>`).join('')}</select></div><div id="table-region">${tableHTML()}</div></section>`;}
function renderClinics(){return `<p class="section-note">Вымышленные клиники и предложения для проверки сценария. Даты и цены — примеры, не действующие условия лечения.</p><div class="clinic-grid">${CLINICS.map(c=>`<article class="clinic-card"><div class="clinic-top"><span class="clinic-icon" aria-hidden="true">⊞</span><div><h3>${c.name}</h3><p>${c.city} · ${PROCEDURES[c.procedure].profile}</p></div></div><div class="clinic-procedure">${PROCEDURES[c.procedure].name}</div><div class="clinic-meta"><div><small>Ближайшая дата в демо</small><strong>${dateLabel(c.date)}</strong></div><div><small>Свободно в сценарии</small><strong>${availableSlots(c)} места</strong></div><div><small>Варианты оплаты</small>${badge(c.payment,'payment')}</div><div><small>${c.payment==='oms'?'Условия':'Пример стоимости'}</small><strong>${c.payment==='oms'?'Приём по ОМС':money(c.price)}</strong></div></div><div class="clinic-bottom"><span class="count-label">${patients.filter(p=>p.status==='waiting'&&matches(p,c)).length} заявок для рассмотрения</span><button class="button secondary" data-clinic-filter="${c.id}">Подобрать пациентов</button></div></article>`).join('')}</div>`;}
function renderJourneys(){const columns=[['Заявка и подбор',['waiting','clarification','review']],['Госпитализация',['confirmed','admitted']],['Итог',['no_show','documents','completed','cancelled']]];return `${statsHTML()}<p class="section-note">Учебный маршрут пациента. Действия не создают настоящего направления и не меняют очередь в больнице.</p><div class="board">${columns.map(([title,statuses])=>{const rows=patients.filter(p=>statuses.includes(p.status));return `<section class="board-column"><div class="board-title">${title}<span>${rows.length}</span></div>${rows.map(p=>`<article class="journey-card"><button class="patient-id" data-open="${p.id}">Пациент Д-${p.id}</button><span class="subline">${ageLabel(p.age)} · ${esc(p.city)}</span><p>${PROCEDURES[p.procedure].name}</p>${badge(p.status)}${p.offer?`<span class="subline">${CLINICS.find(c=>c.id===p.offer.clinicId).name}<br>${dateLabel(p.offer.date)} · ${PAYMENT[p.offer.payment]}</span>`:''}<button class="button secondary" data-open="${p.id}">Открыть маршрут</button></article>`).join('')||'<p class="board-empty">Пока нет заявок на этом этапе.</p>'}</section>`}).join('')}</div>`;}
function renderAbout(){return `<div class="about-grid"><section class="about-card"><p class="eyebrow">ПРОЙДИТЕ ПУТЬ ЗАЯВКИ</p><h2>От первичного звена до госпитализации</h2><ol><li><strong>Врач амбулатории создаёт заявку.</strong> В своём режиме он видит только собственные пробные записи.</li><li><strong>Врач стационара рассматривает общий список.</strong> Подбирает клинику по профилю, оплате и готовности пациента ехать.</li><li><strong>Стационар предлагает дату и условия.</strong> В сценарии заявка переходит на согласование.</li><li><strong>Пациент отслеживает ход заявки.</strong> Для демонстрации откройте его роль в переключателе сверху.</li><li><strong>Администратор видит общий реестр.</strong> В прототипе отдельные настройки учётных записей не реализованы.</li></ol><a href="#patients" class="button primary">Открыть заявки</a></section><section class="about-card"><p class="eyebrow">ГРАНИЦЫ ПРОТОТИПА</p><h2>Только вымышленные данные</h2><p>Пациенты, клиники, цены и предложения придуманы. Изменения хранятся только в текущей вкладке и сбрасываются после перезагрузки.</p><p>Переключатель ролей нужен только для обсуждения сценариев. Здесь можно проверить черновик, изменение своей заявки, уточнения, несколько предложений, исход контакта, календарь, статусы, архив и журнал демо. Это не авторизация и не защита данных.</p><p>Публичная демоверсия намеренно не принимает ФИО, дату рождения, полис, диагнозы, контакты и медицинские документы. Полная анкета, справочники МКБ/ТФОМС, проверка дублей, согласия и защищённые файлы проектируются для серверной версии.</p><h3>Поля защищённой анкеты из ТЗ</h3><p>ФИО, дата рождения, пол, город, контакт пациента/представителя, номер полиса (без СНИЛС по текущему ТЗ), диагноз и код МКБ-10, операция и код ТФОМС, текст анализов или файлы PDF/PNG/JPG/JPEG, комментарий, законный представитель, способ лечения и основание передачи. Требуется хотя бы описание анализов или вложение; лимит файла в ТЗ — до 100 МБ.</p><p>Нет настоящей базы, учётных записей, уведомлений, восстановления после потери связи и защищённого аудита. Изменения доступны только в текущей вкладке браузера.</p><p>Совпадение по параметрам не является медицинской рекомендацией. Показания и возможность госпитализации оценивает врач.</p><p>До использования с реальными пациентами нужно спроектировать защищённую инфраструктуру, роли и аудит, правовые основания обработки и порядок передачи сведений между медорганизациями.</p></section></div>`;}
function renderArchitecture(){return `<div class="about-grid"><section class="about-card"><p class="eyebrow">СХЕМА СЕРВЕРНОЙ ВЕРСИИ</p><h2>Сайт не подключается к базе напрямую</h2><p>Браузер врача или пациента → API Антона → PostgreSQL на закрытом сервере. Файлы анализов хранятся отдельно в закрытом объектном хранилище.</p><ol><li>Браузер отправляет запрос по HTTPS.</li><li>API проверяет пользователя, роль, учреждение и доступ к конкретной заявке.</li><li>Сервер проверяет данные, сохраняет изменения в БД и пишет событие в аудит.</li><li>Браузер получает только разрешённые для этой роли сведения.</li></ol></section><section class="about-card"><p class="eyebrow">ГДЕ ХРАНИТЬ ДАННЫЕ</p><h2>Разделить базу, файлы и копии</h2><ul class="storage-list"><li><strong>PostgreSQL</strong><span>Учётные записи, организации, заявки, коды МКБ и операций, предложения, статусы, согласия и история.</span></li><li><strong>Закрытое файловое хранилище</strong><span>Анализы и документы; сервер выдаёт временный доступ только после проверки прав.</span></li><li><strong>Зашифрованные резервные копии</strong><span>Отдельная площадка, ограниченный доступ, регулярная проверка восстановления.</span></li></ul><p><strong>Не хранить в GitHub Pages, исходниках, localStorage или публичных облачных папках.</strong> Не открывать PostgreSQL в интернет и не помещать пароль БД в JavaScript сайта.</p><p>Для пилота выбирайте контролируемую инфраструктуру с размещением серверов в России и согласуйте её с ответственными за безопасность и обработку данных.</p></section><section class="about-card"><p class="eyebrow">КАК САЙТ ОБРАЩАЕТСЯ К API</p><h2>Браузер → API → база</h2><p>Например, сайт запрашивает заявки текущего врача:</p><pre class="code-example"><code>fetch('/api/referrals?scope=mine', { credentials: 'include' })</code></pre><p>API выполняет запрос в PostgreSQL от имени серверного приложения. Логин и пароль БД хранятся только на сервере в защищённых настройках.</p><p><code>POST /api/referrals</code> создаёт заявку; <code>GET /api/referrals/:id</code> открывает карточку с проверкой доступа; <code>POST /api/referrals/:id/offers</code> добавляет предложение; <code>POST /api/referrals/:id/status</code> меняет статус.</p><a class="button secondary" href="https://github.com/ArtemiiPihalych/medroute-demo/blob/main/ARCHITECTURE.md">Техническая схема, таблицы и этапы разработки</a></section><section class="about-card"><p class="eyebrow">ВАЖНО</p><h2>Этот сайт пока работает без сервера</h2><p>Роли здесь — только демонстрация. Пробные заявки меняются в памяти вкладки и исчезают после перезагрузки. Реальные данные вводить нельзя.</p><p>Для рабочей версии нужны серверный API, настоящая авторизация, проверка прав на сервере, аудит и резервное копирование. Номер полиса или СНИЛС сам по себе не должен быть паролем пациента: безопасный доступ к статусу проектируется отдельно.</p><a href="#about" class="button primary">Посмотреть сценарий и роли</a></section></div>`;}
function renderCalendar(){const rows=patients.filter(p=>['confirmed','admitted'].includes(p.status)&&p.offer).sort((a,b)=>a.offer.date.localeCompare(b.offer.date));return `<p class="section-note">Только согласованные учебные даты. В этом прототипе календарь не резервирует места и не заменяет расписание стационара.</p><section class="panel"><div class="panel-header"><h2>Плановые госпитализации</h2><span class="count-label">${rows.length} записей в демо</span></div>${rows.length?`<table class="patient-table"><thead><tr><th>Дата</th><th>Пациент</th><th>Вмешательство</th><th>Условия</th><th>Статус</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${dateLabel(p.offer.date)}</td><td><button class="patient-id" data-open="${p.id}">Д-${p.id}</button><span class="subline">${esc(p.city)}</span></td><td>${PROCEDURES[p.procedure].name}</td><td>${PAYMENT[p.offer.payment]}</td><td>${badge(p.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h3>Согласованных дат пока нет</h3><p>Запись появится после подтверждения предложения в демонстрационном сценарии.</p></div>'}</section>`;}
function renderStatistics(){const n=counts();const finished=patients.filter(p=>p.status==='completed').length;const offered=patients.filter(p=>['review','confirmed','admitted','completed'].includes(p.status)).length;const cancelled=patients.filter(p=>p.status==='cancelled').length;return `<p class="section-note">Сводные показатели по вымышленным записям. В реальной системе статистика должна агрегироваться так, чтобы нельзя было определить пациента.</p><div class="stats"><div class="stat"><span>Новых заявок</span><strong>${n.all}</strong><small>В текущем демо</small></div><div class="stat"><span>Есть предложение</span><strong>${offered}</strong><small>Учебные предложения</small></div><div class="stat"><span>Отменено</span><strong>${cancelled}</strong><small>Демо-статусы</small></div><div class="stat accent"><span>Случай завершён</span><strong>${finished} / 30</strong><small>Целевое значение пилота за месяц</small></div></div><section class="about-card"><h2>Метрики пилота из ТЗ</h2><p>Длительность от создания до первого предложения и до завершения случая; количество новых, активных, отменённых и завершённых заявок; предложения, отказы и неявки. Месяц отчёта и старт отсчёта должны быть утверждены до запуска.</p><p class="muted">Эти демонстрационные счётчики не используют реальные данные и не рассчитывают клинические показатели.</p></section>`;}
function renderArchive(){const rows=patients.filter(p=>p.status==='archived');return `<p class="section-note">Архивные записи скрыты из активной очереди, но сохраняют историю. Архивирование не означает удаление данных.</p><section class="panel"><div class="panel-header"><h2>Архив</h2><span class="count-label">${rows.length} записей</span></div>${rows.length?`<div class="archive-list">${rows.map(p=>`<article class="journey-card"><button class="patient-id" data-open="${p.id}">Д-${p.id}</button><span class="subline">${PROCEDURES[p.procedure].name} · ${esc(p.city)}</span><p>Причина: ${esc(p.statusReason||'не указана')}</p><span class="subline">${p.history.at(-1)?.time||''}</span></article>`).join('')}</div>`:'<div class="empty"><h3>Архив пуст</h3><p>Администратор может архивировать неактуальную заявку с указанием причины.</p></div>'}</section>`;}
function renderAudit(){return `<p class="section-note">Локальный журнал действий демонстрации. Он не является защищённым аудитом и исчезает после перезагрузки.</p><section class="panel"><div class="panel-header"><h2>История действий</h2><span class="count-label">${auditLog.length} событий</span></div>${auditLog.length?`<ol class="audit-list">${auditLog.map(item=>`<li><strong>${esc(item.text)}</strong><span>Д-${item.id} · ${esc(item.role)} · ${esc(item.time)}</span></li>`).join('')}</ol>`:'<div class="empty"><h3>Действий пока нет</h3><p>Открытие карточек и изменения статусов появятся здесь в текущем сеансе.</p></div>'}</section>`;}
function renderTrack(){const p=patients.find(p=>p.id===1042);const steps=[['Заявка создана','Заявка зарегистрирована в системе'],['Идёт подбор','Стационары рассматривают возможность приёма'],['Предложение стационара','Пациенту предложат дату и условия'],['Госпитализация','Дата и место приёма согласованы']];const active=['draft','waiting','clarification'].includes(p.status)?1:p.status==='review'?2:3;const nextStep=p.status==='review'?'Врач стационара сообщит результат рассмотрения предложения.':p.status==='confirmed'?'Подготовьте документы, о которых сообщил стационар.':p.status==='admitted'?'Ожидайте завершения лечения и обновления статуса.':p.status==='completed'?'Маршрут завершён.':p.status==='no_show'?'Свяжитесь с врачом, чтобы обсудить дальнейшие действия.':p.status==='documents'?'Уточните у врача, какие документы нужно предоставить.':'Ожидайте предложения стационара; врач свяжется с вами.';return `<section class="track-card"><p class="eyebrow">ЛИЧНЫЙ СТАТУС · ДЕМО</p><h2>Заявка Д-${p.id}</h2><p class="muted">Это экран пациента в демонстрационном режиме. В реальной системе статус будет доступен только после безопасной проверки личности.</p><div class="track-status">${badge(p.status)}<span>Обновлено: ${p.history.at(-1).time}</span></div><p class="next-step"><strong>Следующий шаг:</strong> ${nextStep}</p><ol class="track-steps">${steps.map(([title,description],i)=>`<li class="${i<active?'done':i===active?'current':''}"><span class="step-marker">${i<active?'✓':i+1}</span><div><strong>${title}</strong><p>${description}</p></div></li>`).join('')}</ol>${p.offer?`<div class="track-offer"><strong>Предложенный стационар</strong><p>${CLINICS.find(c=>c.id===p.offer.clinicId).name} · ${dateLabel(p.offer.date)} · ${PAYMENT[p.offer.payment]}</p></div>`:'<div class="track-offer"><strong>Пока без предложений</strong><p>Подходящий стационар ещё не выбран.</p></div>'}</section>`;}
function render(){const info={patients:[role==='outpatient'?'Мои заявки':'Пациенты',role==='outpatient'?'Заявки, созданные этим врачом амбулатории.':'Помогаем найти подходящий стационар и согласовать лечение.'],clinics:['Возможности клиник','Предложения по плановой помощи в Челябинской области.'],journeys:['Госпитализации','Каждая заявка — с понятным следующим шагом.'],calendar:['Календарь','Согласованные даты плановых госпитализаций.'],statistics:['Статистика','Агрегированные показатели пилота.'],archive:['Архив','Неактуальные заявки с сохранённой историей.'],audit:['Аудит демо','История действий в текущем сеансе.'],about:['Как работает демо','Проверьте сценарий вместе с врачами перед разработкой реальной системы.'],architecture:['Данные и подключение','Как перейти от демоверсии к серверной системе.'],track:['Статус заявки','Пациент видит ход рассмотрения своей заявки.']}[view];
  document.getElementById('page-title').textContent=info[0];document.getElementById('crumb').textContent=info[0];document.getElementById('page-description').textContent=info[1];document.getElementById('nav-count').textContent=visiblePatients().length;document.getElementById('patients-nav-label').textContent=role==='outpatient'?'Мои заявки':'Пациенты';document.getElementById('add-patient').hidden=view==='about'||view==='architecture'||view==='track'||role==='patient';document.getElementById('role-switch').value=role;
  const navViews=role==='patient'?['track','architecture']:role==='outpatient'?['patients','about','architecture']:role==='admin'?['patients','clinics','journeys','calendar','statistics','archive','audit','about','architecture']:['patients','clinics','journeys','calendar','about','architecture'];document.querySelectorAll('[data-view]').forEach(a=>{a.hidden=!navViews.includes(a.dataset.view);});document.querySelector('.user strong').textContent=ROLE[role];document.querySelector('.user small').textContent='Демонстрационная роль';
  document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  document.getElementById('content').innerHTML=({patients:renderPatients,clinics:renderClinics,journeys:renderJourneys,calendar:renderCalendar,statistics:renderStatistics,archive:renderArchive,audit:renderAudit,about:renderAbout,architecture:renderArchitecture,track:renderTrack})[view]();
}
function allowedViews(){return role==='patient'?['track','architecture']:role==='outpatient'?['patients','about','architecture']:role==='admin'?['patients','clinics','journeys','calendar','statistics','archive','audit','about','architecture']:['patients','clinics','journeys','calendar','about','architecture'];}
function navigate(){const next=location.hash.slice(1);view=allowedViews().includes(next)?next:(role==='patient'?'track':'patients');render();}
function setView(next){view=next;if(location.hash!==`#${next}`)location.hash=next;else render();}
function detailHTML(p){const proc=PROCEDURES[p.procedure];const candidates=matchingClinics(p);return `<div class="dialog-header"><div><p class="eyebrow">ДЕМОНСТРАЦИОННАЯ ЗАЯВКА</p><h2 id="detail-title">Пациент Д-${p.id}</h2><p class="detail-subtitle">${ageLabel(p.age)} · ${p.city} · Добавлен ${dateLabel(p.created)}</p></div><button class="icon-button" data-close="detail-dialog" aria-label="Закрыть карточку">×</button></div>${badge(p.status)}${examFlag(p)}<div class="detail-grid"><div><section class="detail-section"><h3>Потребность в лечении</h3><dl class="detail-info"><div class="span-2"><dt>Планируемое вмешательство</dt><dd><strong>${proc.name}</strong></dd></div><div class="span-2"><dt>Диагноз в учебном примере</dt><dd>${proc.diagnosis}</dd></div><div><dt>Оплата</dt><dd>${PAYMENT[p.payment]}</dd></div><div><dt>Обследования</dt><dd>${p.ready?'Собраны в демо':'Нужны уточнения'}</dd></div>${(role==='inpatient'||role==='admin')?`<div class="span-2"><dt>Очный осмотр</dt><dd>${p.inPersonRequired?'Требуется':'Не требуется'}</dd></div>`:''}<div class="span-2"><dt>География</dt><dd>${p.travel?'Рассматривает другие города области':`Только ${p.city}`}</dd></div></dl><p class="detail-note">Все случаи в демо — плановые. Подбор по параметрам требует последующей оценки врачом.</p></section><section class="detail-section"><h3>Контакты и документы</h3><p class="muted">Вымышленный пациент. Телефон, ФИО и медицинские документы отсутствуют.</p></section><section class="detail-section"><h3>История заявки</h3><ol class="timeline">${p.history.map(h=>`<li>${esc(h.text)}<small>${esc(h.time)}</small></li>`).join('')}</ol></section></div><section><div class="match-title"><h3>${p.status==='waiting'?'Подходящие предложения':'Выбранный вариант'}</h3>${p.status==='waiting'?`<span>${candidates.length} найдено</span>`:''}</div>${!p.ready?'<p class="detail-warning">Обследования требуют уточнения. В демо можно предложить вариант, но подтверждение приёма доступно после отметки о готовности.</p>':''}<div id="offer-region">${p.status==='waiting'?(candidates.length?candidates.map(c=>`<article class="match-card"><h4>${c.name}</h4><p>${c.city} · С ${dateLabel(c.date)} · ${availableSlots(c)} места</p><p>${c.payment==='oms'?'Приём по ОМС':`Доступно: ${PAYMENT[c.payment]} · Пример цены ${money(c.price)}`}</p><button class="button primary" data-stage="${c.id}">Предложить вариант</button></article>`).join(''):'<div class="empty"><h3>Совпадений пока нет</h3><p>В демо нет предложения с подходящими вмешательством, оплатой и городом. Заявка остаётся в ожидании.</p></div>'):currentOfferHTML(p)}</div></section></div>`;}
function nextStatuses(p){const map={draft:['waiting','cancelled'],waiting:['clarification','cancelled'],clarification:['waiting','cancelled'],review:['waiting','cancelled'],confirmed:['admitted','no_show','documents','cancelled'],admitted:['completed'],no_show:['waiting','completed','cancelled'],documents:['waiting','completed','cancelled'],completed:['cancelled'],cancelled:[]};const next=map[p.status]||[];if(role==='admin'&&!['archived','draft'].includes(p.status))next.push('archived');return next;}
function statusActionHTML(p){if(!['inpatient','admin'].includes(role))return '';const next=nextStatuses(p);if(!next.length)return '';return `<section class="status-actions"><h3>Следующий этап</h3><form id="status-form"><label>Изменить статус<select name="status" required>${next.map(s=>`<option value="${s}">${STATUS[s]}</option>`).join('')}</select></label><label>Основание / результат контакта<input name="reason" type="text" minlength="3" maxlength="300" placeholder="Кратко укажите причину или результат" required></label><button class="button secondary" type="submit">Сохранить статус</button></form></section>`;}
function contactActionsHTML(p){if(!['inpatient','admin'].includes(role))return '';const contacts=p.contacts||[];return `<section class="status-actions"><h3>Контакт с пациентом</h3>${contacts.map(c=>`<p class="muted">${esc(c.channel)} · ${esc(c.outcome)} · ${esc(c.time)}</p>`).join('')}<form id="contact-form"><label>Канал<select name="channel"><option>Телефон</option><option>Email</option></select></label><label>Итог<select name="outcome"><option>Связались · согласен</option><option>Связались · отказ</option><option>Просьба перезвонить</option><option>Не дозвонились</option></select></label><button class="button secondary" type="submit">Записать контакт</button></form></section>`;}
function openPatient(id){const p=patients.find(p=>p.id===Number(id));if(!p)return;selectedId=p.id;auditLog.unshift({id:p.id,role:ROLE[role],text:'Открыта карточка заявки',time:'Сейчас · действие в демоверсии'});const editAction=role==='outpatient'&&p.createdBy==='amb-1'&&['draft','waiting','clarification'].includes(p.status)?`<button class="button secondary edit-request" data-edit="${p.id}">Редактировать свою заявку</button>`:'';const reply=role==='outpatient'&&p.createdBy==='amb-1'&&p.status==='clarification'?`<form id="clarification-form" class="reply-panel"><label>Ответ врачу стационара<textarea name="reply" rows="3" minlength="3" maxlength="500" required></textarea></label><button class="button primary" type="submit">Отправить ответ в демо</button></form>`:'';document.getElementById('detail-content').innerHTML=detailHTML(p)+editAction+reply+contactActionsHTML(p)+statusActionHTML(p);openDialog('detail-dialog');}
function offerCardsHTML(candidates){return candidates.length?candidates.map(c=>`<article class="match-card"><h4>${c.name}</h4><p>${c.city} · С ${dateLabel(c.date)} · ${availableSlots(c)} места</p><p>${c.payment==='oms'?'Приём по ОМС':`Доступно: ${PAYMENT[c.payment]} · Пример цены ${money(c.price)}`}</p><button class="button primary" data-stage="${c.id}">Предложить вариант</button></article>`).join(''):'<div class="empty"><h3>Новых совпадений нет</h3><p>Доступные варианты для этой заявки уже добавлены или отсутствуют.</p></div>';}
function currentOfferHTML(p){const offers=p.offers|| (p.offer?[p.offer]:[]);if(!p.offer)return `<div class='offer-panel'><strong>${p.status==='draft'?'Черновик не опубликован':'Предложения пока нет'}</strong><p>Следующий этап будет доступен после проверки заявки.</p></div>`;const c=CLINICS.find(c=>c.id===p.offer.clinicId);if(p.status==='review')return `<div class='offer-panel'><h3>Предложения стационаров</h3>${offers.map(o=>{const clinic=CLINICS.find(c=>c.id===o.clinicId);return `<p>${clinic.name} · ${dateLabel(o.date)} · ${PAYMENT[o.payment]}</p>`}).join('')}<form id='confirm-form'><label>Пациент выбрал вариант<select name='offerId'>${offers.map(o=>{const clinic=CLINICS.find(c=>c.id===o.clinicId);return `<option value='${o.id}'>${clinic.name} · ${dateLabel(o.date)} · ${PAYMENT[o.payment]}</option>`}).join('')}</select></label>${!p.ready?'<label class="checkbox-label"><input type="checkbox" name="ready" required>В сценарии обследования проверены врачом</label>':''}<label class='checkbox-label'><input type='checkbox' name='agreed' required>Пациент сообщил врачу о согласии на выбранный вариант</label><button class='button primary' type='submit'>Подтвердить выбранный вариант в демо</button></form><button class='button secondary' data-add-offer>Добавить ещё предложение</button><button class='text-button' data-withdraw>Снять предложения и вернуть к подбору</button></div>`;return `<div class='offer-panel'><h3>${c.name}</h3><p>${c.city}<br><strong>${dateLabel(p.offer.date)} · ${PAYMENT[p.offer.payment]}</strong></p><p class='ready'>✓ ${esc(STATUS[p.status]||'Статус обновлён')} в учебном сценарии</p></div>`;}
function stageOffer(clinicId){const p=patients.find(p=>p.id===selectedId);const c=CLINICS.find(c=>c.id===clinicId);if(!p||!['waiting','review'].includes(p.status)||!c||!matches(p,c)||availableSlots(c)<1)return;
  const pays=['oms','paid'].filter(pay=>compatiblePayment(p.payment,pay)&&compatiblePayment(c.payment,pay));
  document.getElementById('offer-region').innerHTML=`<form class="offer-panel" id="offer-form" data-clinic="${c.id}"><h3>${c.name}</h3><p>Пробное предложение пациенту Д-${p.id}. Связь с пациентом не выполняется.</p><label>Условия приёма<select name="payment">${pays.map(pay=>`<option value="${pay}">${pay==='oms'?'По ОМС':`Платно · пример ${money(c.price)}`}</option>`).join('')}</select></label><label>Предлагаемая дата в сценарии<input type="date" name="date" min="${c.date}" max="2026-12-31" value="${c.date}" required></label><p class="muted">Предложение не бронирует место. Возможность приёма проверяется при подтверждении.</p><button class="button primary" type="submit">Создать пробное предложение</button><button class="text-button" type="button" data-back-detail>Вернуться к предложениям</button></form>`;
  document.querySelector('#offer-form select').focus();
}
function addHistory(p,text){p.history.push({text,time:'Сейчас · действие в демоверсии'});auditLog.unshift({id:p.id,role:ROLE[role],text,time:'Сейчас · действие в демоверсии'});}

patients=initialPatients();resetFilters();
document.getElementById('procedure-select').innerHTML=PROCEDURES.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('');
document.getElementById('role-switch').addEventListener('change',e=>{role=e.target.value;resetFilters();view=role==='patient'?'track':'patients';if(location.hash!==`#${view}`)location.hash=view;else render();});
window.addEventListener('hashchange',navigate);
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-clinic-filter]');if(!b)return;
  if(b.dataset.close){closeDialog(b.dataset.close);return;}
  if(b.dataset.open){openPatient(b.dataset.open);return;}
  if(b.hasAttribute('data-status')){filters.status=b.dataset.status;render();return;}
  if(b.hasAttribute('data-reset-filters')){resetFilters();render();return;}
  if(b.dataset.clinicFilter){resetFilters();clinicFilter=b.dataset.clinicFilter;filters.status='waiting';setView('patients');return;}
  if(b.dataset.stage){stageOffer(b.dataset.stage);return;}
  if(b.hasAttribute('data-add-offer')){const p=patients.find(p=>p.id===selectedId);if(!p||p.status!=='review')return;document.getElementById('offer-region').innerHTML=`${offerCardsHTML(matchingClinics(p))}<button class="text-button" data-back-detail>Вернуться к предложениям</button>`;return;}
  if(b.hasAttribute('data-back-detail')){openPatient(selectedId);return;}
  if(b.hasAttribute('data-withdraw')){const p=patients.find(p=>p.id===selectedId);p.status='waiting';p.offer=null;p.offers=[];addHistory(p,'Предложения сняты в демо, возобновлён подбор');render();openPatient(p.id);announce('Предложения сняты. Заявка возвращена к подбору.');return;}
  if(b.dataset.edit){const p=patients.find(p=>p.id===Number(b.dataset.edit));if(!p||role!=='outpatient'||p.createdBy!=='amb-1')return;editingId=p.id;const f=document.getElementById('patient-form');f.reset();f.elements.age.value=p.age;f.elements.city.value=p.city;f.elements.procedure.value=p.procedure;f.elements.payment.value=p.payment;f.elements.ready.value=String(p.ready);f.elements.travel.checked=p.travel;f.elements.inPersonRequired.checked=p.inPersonRequired;document.getElementById('form-title').textContent=`Редактирование Д-${p.id}`;closeDialog('detail-dialog');openDialog('form-dialog');return;}
  if(b.id==='add-patient'){editingId=null;document.getElementById('patient-form').reset();document.getElementById('form-title').textContent='Пробная заявка';openDialog('form-dialog');return;}
  if(b.id==='reset'){openDialog('reset-dialog');return;}
  if(b.id==='confirm-reset'){patients=initialPatients();auditLog=[];resetFilters();closeDialog('reset-dialog');render();announce('Исходные примеры восстановлены.');}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.search=e.target.value;document.getElementById('table-region').innerHTML=tableHTML();}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;document.getElementById('table-region').innerHTML=tableHTML();}});
document.addEventListener('submit',e=>{
  if(!['patient-form','offer-form','confirm-form','status-form','clarification-form','contact-form'].includes(e.target.id))return;e.preventDefault();const f=e.target;const data=new FormData(f);
  if(f.id==='patient-form'){
    const age=Number(data.get('age')),procedure=Number(data.get('procedure')),payment=data.get('payment'),city=data.get('city');
    if(!Number.isInteger(age)||age<18||age>100||!PROCEDURES[procedure]||!PAYMENT[payment]||!['Челябинск','Магнитогорск','Златоуст','Миасс','Копейск','Сатка'].includes(city))return;
    if(editingId){const p=patients.find(p=>p.id===editingId);if(!p||role!=='outpatient'||p.createdBy!=='amb-1')return;const wasDraft=p.status==='draft';p.age=age;p.city=city;p.procedure=procedure;p.payment=payment;p.ready=data.get('ready')==='true';p.travel=data.has('travel');p.inPersonRequired=data.has('inPersonRequired');if(wasDraft&&e.submitter?.value==='publish')p.status='waiting';else if(!wasDraft)p.needsReview=true;addHistory(p,wasDraft?(p.status==='waiting'?'Черновик проверен и отправлен стационару':'Черновик изменён'):'Автор изменил опубликованную заявку; требуется повторная проверка стационаром');const id=p.id;editingId=null;closeDialog('form-dialog');resetFilters();render();openPatient(id);announce(`Заявка Д-${id} обновлена в демо.`);return;}
    const id=Math.max(...patients.map(p=>p.id))+1;
    const saveMode=e.submitter?.value==='draft'?'draft':'waiting';
    patients.unshift({id,age,city,procedure,payment,ready:data.get('ready')==='true',travel:data.has('travel'),inPersonRequired:data.has('inPersonRequired'),status:saveMode,createdBy:role==='outpatient'?'amb-1':role==='admin'?'admin':'hospital',created:'2026-10-03',offer:null,history:[{text:saveMode==='draft'?'Сохранён черновик заявки':'Создана пробная заявка',time:'Сейчас · действие в демоверсии'}]});
    closeDialog('form-dialog');resetFilters();view='patients';if(location.hash!=='#patients')location.hash='patients';render();announce(saveMode==='draft'?`Черновик Д-${id} сохранён в этой вкладке.`:`Заявка Д-${id} отправлена в демо.`);
  }
  if(f.id==='offer-form'){
    const p=patients.find(p=>p.id===selectedId),c=CLINICS.find(c=>c.id===f.dataset.clinic);const payment=data.get('payment'),date=data.get('date');
    if(!p||!['waiting','review'].includes(p.status)||!c||!matches(p,c)||availableSlots(c)<1||!['oms','paid'].includes(payment)||!compatiblePayment(p.payment,payment)||!compatiblePayment(c.payment,payment)||!/^2026-\d{2}-\d{2}$/.test(date)||date<c.date||date>'2026-12-31')return;
    const offer={id:`offer-${p.id}-${Date.now()}`,clinicId:c.id,payment,date};p.offers=p.offers||[];p.offers.push(offer);p.offer=offer;p.status='review';addHistory(p,`Предложено: ${c.name}, ${dateLabel(date)}, ${PAYMENT[payment]}`);render();openPatient(p.id);announce('Пробное предложение добавлено. Связь с пациентом не выполняется.');
  }
  if(f.id==='confirm-form'){
    const p=patients.find(p=>p.id===selectedId);if(!p||p.status!=='review'||!data.has('agreed')||(!p.ready&&!data.has('ready')))return;
    const selected=(p.offers||[]).find(o=>o.id===data.get('offerId'))||p.offer;p.offer=selected;p.offers=(p.offers||[]).map(o=>({...o,state:o.id===selected.id?'confirmed':'closed'}));const c=CLINICS.find(c=>c.id===selected.clinicId);if(availableSlots(c)<1){const message=document.createElement('p');message.className='detail-warning';message.textContent='Все места в этом сценарии уже заняты. Верните заявку к подбору.';f.replaceWith(message);return;}
    if(!p.ready){p.ready=true;addHistory(p,'Готовность обследований подтверждена в демо');}p.status='confirmed';addHistory(p,'Пациент и клиника согласовали госпитализацию в демо; остальные предложения закрыты');render();openPatient(p.id);announce('Приём подтверждён только в учебном сценарии.');
  }
  if(f.id==='status-form'){
    const p=patients.find(p=>p.id===selectedId),next=data.get('status'),reason=String(data.get('reason')||'').trim();if(!p||!nextStatuses(p).includes(next)||reason.length<3)return;
    const previous=p.status;if(previous==='review'&&next==='waiting'){p.offer=null;p.offers=[];}p.status=next;p.statusReason=reason;addHistory(p,`Статус изменён: «${STATUS[previous]}» → «${STATUS[next]}». Основание: ${reason}`);render();openPatient(p.id);announce(`Статус заявки изменён на «${STATUS[next]}».`);
  }
  if(f.id==='clarification-form'){
    const p=patients.find(p=>p.id===selectedId),reply=String(data.get('reply')||'').trim();if(!p||role!=='outpatient'||p.createdBy!=='amb-1'||p.status!=='clarification'||reply.length<3)return;p.clarificationReply=reply;p.status='waiting';addHistory(p,'Автор ответил на запрос уточнения');render();openPatient(p.id);announce('Ответ врачу сохранён только в демо.');
  }
  if(f.id==='contact-form'){
    const p=patients.find(p=>p.id===selectedId);if(!p||!['inpatient','admin'].includes(role))return;p.contacts=p.contacts||[];const contact={channel:String(data.get('channel')),outcome:String(data.get('outcome')),time:'Сейчас · действие в демоверсии'};p.contacts.push(contact);addHistory(p,`Контакт (${contact.channel}): ${contact.outcome}`);render();openPatient(p.id);announce('Результат контакта записан только в демо.');
  }
});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
navigate();

// Optional browser WebMCP: read the same synthetic registry shown in the UI.
if(document.modelContext?.registerTool){
  const life=new AbortController();
  try{Promise.resolve(document.modelContext.registerTool({name:'read_demo_referrals',description:'Read synthetic referrals in the Anton demo. No real patient data. Optional status filter.',inputSchema:{type:'object',properties:{status:{type:'string',enum:['waiting','review','confirmed']}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>k!=='status')||(input.status!==undefined&&!Object.hasOwn(STATUS,input.status)))throw new Error('Invalid status filter');return patients.filter(p=>!input.status||p.status===input.status).map(p=>({id:`Д-${p.id}`,city:p.city,procedure:PROCEDURES[p.procedure].name,status:STATUS[p.status],payment:PAYMENT[p.payment]}));}}, {signal:life.signal})).catch(()=>{});}catch{/* Optional API: the demo works without it. */}
  window.addEventListener('pagehide',()=>life.abort(),{once:true});
}
